#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n <= 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 30) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    uint64_t catalan[31] = {0};
    catalan[0] = 1;
    for (int k = 1; k <= n; ++k) {
        uint64_t sum = 0;
        for (int i = 0; i < k; ++i) {
            sum += catalan[i] * catalan[k - 1 - i];
        }
        catalan[k] = sum;
    }
    printf("%" PRIu64 "\n", catalan[n - 1]);
    return 0;
}
